// sprintfBinding is a String binding that formats multiple DataItems using fmt.Sprintf
type sprintfBinding struct {
	base
	format   string
	sources  []DataItem
	listener DataListener
}

// NewSprintf creates a String binding that formats multiple bindings using fmt.Sprintf.
// The format string follows the same rules as fmt.Sprintf.
// When any source binding changes, the formatted result is automatically updated.
//
// Example:
//   name := binding.NewString()
//   age := binding.NewInt()
//   formatted := binding.NewSprintf("Name: %s, Age: %d", name, age)
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:  format,
		sources: bindings,
	}

	// Create a listener that triggers when any source changes
	s.listener = NewDataListener(func() {
		s.trigger()
	})

	// Attach listener to all source bindings
	for _, source := range s.sources {
		source.AddListener(s.listener)
	}

	return s
}

